```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create function public.is_team_member(p_team_id bigint, p_role text)
returns boolean as $$
  select exists (
    select 1 from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = p_role
  );
$$ language sql security definer;

create function public.is_team_member_any_role(p_team_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$ language sql security definer;

create policy "Users can view their own teams"
on public.teams
for select
to authenticated
using (
  exists (
    select 1 from public.team_members tm
    where tm.team_id = id
      and tm.user_id = auth.uid()
  )
);

create policy "Users can view their own memberships"
on public.team_members
for select
to authenticated
using (
  user_id = auth.uid()
);

create policy "Members can read team documents (non-deleted)"
on public.documents
for select
to authenticated
using (
  deleted_at is null
  and public.is_team_member_any_role(team_id)
);

create policy "Editors can create documents in their teams"
on public.documents
for insert
to authenticated
with check (
  created_by = auth.uid()
  and public.is_team_member(team_id, 'editor')
);

create policy "Editors can update documents in their teams"
on public.documents
for update
to authenticated
using (
  public.is_team_member(team_id, 'editor')
)
with check (
  public.is_team_member(team_id, 'editor')
);

create policy "Only creator can delete documents"
on public.documents
for delete
to authenticated
using (
  created_by = auth.uid()
  and deleted_at is null
);

revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;

grant usage on schema public to authenticated;
grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;
```

