```sql
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create function public.is_suspended() returns boolean as $$
  select exists (
    select 1 from public.accounts where user_id = auth.uid() and suspended = true
  );
$$ language sql security definer;

create policy "Accounts: authenticated users can read own account"
  on public.accounts
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "Files: owners can create files"
  on public.files
  for insert
  to authenticated
  with check (owner_id = auth.uid());

create policy "Files: owners can read own files"
  on public.files
  for select
  to authenticated
  using (owner_id = auth.uid());

create policy "Files: owners can update own files"
  on public.files
  for update
  to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy "Files: owners can delete own files"
  on public.files
  for delete
  to authenticated
  using (owner_id = auth.uid());

create policy "Files: shared users can read files"
  on public.files
  for select
  to authenticated
  using (
    exists (
      select 1 from public.file_shares fs
      where fs.file_id = files.id
        and fs.shared_with = auth.uid()
        and fs.expires_at is null or fs.expires_at > now()
    )
  );

create policy "Files: shared users with edit can update files"
  on public.files
  for update
  to authenticated
  using (
    exists (
      select 1 from public.file_shares fs
      where fs.file_id = files.id
        and fs.shared_with = auth.uid()
        and fs.can_edit = true
        and (fs.expires_at is null or fs.expires_at > now())
    )
  )
  with check (
    exists (
      select 1 from public.file_shares fs
      where fs.file_id = files.id
        and fs.shared_with = auth.uid()
        and fs.can_edit = true
        and (fs.expires_at is null or fs.expires_at > now())
    )
  );

create policy "Files: shared users cannot delete files"
  on public.files
  for delete
  to authenticated
  using (false);

create policy "File Shares: owners can read own file shares"
  on public.file_shares
  for select
  to authenticated
  using (
    exists (
      select 1 from public.files f
      where f.id = file_shares.file_id
        and f.owner_id = auth.uid()
    )
  );

create policy "File Shares: users can read shares addressed to them"
  on public.file_shares
  for select
