create function public.is_issue_visible_to_member(p_issue_id bigint)
returns boolean as $$
  declare
    v_project_id bigint;
    v_is_confidential boolean;
    v_role text;
  begin
    select project_id, is_confidential into v_project_id, v_is_confidential
    from public.issues where id = p_issue_id;

    if v_project_id is null then
      return false;
    end if;

    select role into v_role from public.project_members
    where project_id = v_project_id and user_id = auth.uid();

    if v_role is null then
      return false;
    end if;

    if not v_is_confidential then
      return true;
    end if;

    if v_role = 'maintainer' then
      return true;
    end if;

    if public.is_issue_reporter(p_issue_id) then
      return true;
    end if;

    if public.is_issue_assignee(p_issue_id) then
      return true;
    end if;

    return false;
  end;
