create function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_sign_order integer;
  v_recipient_count integer;
  v_signed_count integer;
  v_current_order integer;
begin
  -- Check if caller is a recipient
  if not public.is_recipient_of_envelope(p_envelope_id) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- Get current status
  v_status := public.get_envelope_status(p_envelope_id);

  -- Check if envelope is still 'sent'
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Get current sign order for caller
  v_sign_order := public.get_recipient_sign_order(p_envelope_id);
  if v_sign_order is null then
    raise exception 'Could not determine sign order';
  end if;

  -- Check if caller has already signed
  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = auth.uid()
      and r.signed_at is not null
  ) then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- Check if all previous recipients have signed
  v_signed_count := public.get_signed_recipient_count(p_envelope_id);
  v_recipient_count := public.get_recipient_count(p_envelope_id);

  if v_signed_count >= v_recipient_count then
    raise exception 'All recipients have already signed';
  end if;

  -- Check if any recipient with lower sign_order has not signed
  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.sign_order < v_sign_order
      and r.signed_at is null
  ) then
    raise exception 'A recipient earlier in sign_order has not signed yet';
  end if;

  -- Record signature
  insert into public.envelope_recipients (envelope_id, user_id, sign_order, signed_at)
  values (p_envelope_id, auth.uid(), v_sign_order, now());

  -- Check if all recipients have signed
  v_signed_count := public.get_signed_recipient_count(p_envelope_id);
  v_recipient_count := public.get_recipient_count(p_envelope_id);

  if v_signed_count = v_recipient_count then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  return public.get_envelope_status(p_envelope_id);
end;
$$;

create function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
begin
  -- Check if caller is the sender
  if not public.is_sender_of_envelope(p_envelope_id) then
    raise exception 'Caller is not the sender of this envelope';
  end if;

  -- Get current status
  v_status := public.get_envelope_status(p_envelope_id);

  -- Check if envelope is still 'sent'
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Void the envelope
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return public.get_envelope_status(p_envelope_id);
end;
$$;

