create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_envelope record;
  v_user_id uuid;
  v_sign_order integer;
  v_signed_at timestamptz;
  v_completed boolean;
begin
  -- Get envelope details
  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  -- Check if envelope is in 'sent' status
  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Check if user is a recipient
  select user_id, sign_order, signed_at
  into v_user_id, v_sign_order, v_signed_at
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  if not found then
    raise exception 'User is not a recipient of this envelope';
  end if;

  -- Check if user has already signed
  if v_signed_at is not null then
    raise exception 'User has already signed this envelope';
  end if;

  -- Check if all previous recipients have signed
  if (select count(*) from public.envelope_recipients
       where envelope_id = p_envelope_id
         and sign_order < v_sign_order) > 0
  then
    if (select count(*) from public.envelope_recipients
         where envelope_id = p_envelope_id
           and sign_order < v_sign_order
           and signed_at is null) > 0
    then
      raise exception 'Previous recipients have not signed yet';
    end if;
  end if;

  -- Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  -- Check if all recipients have signed
  select count(*) > 0 into v_completed
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and signed_at is null;

  if not v_completed then
    raise exception 'Not all recipients have signed yet';
  end if;

  -- Update envelope status to completed
  update public.envelopes
  set status = 'completed'
  where id = p_envelope_id;

  return 'completed';
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_envelope record;
begin
  -- Get envelope details
  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  -- Check if user is the sender
  if v_envelope.sender_id != auth.uid() then
    raise exception 'Only the sender can void an envelope';
  end if;

  -- Check if envelope is in 'sent' status
  if v_envelope.status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Update envelope status to voided
  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;

